const body = $input.item.json.body || $input.item.json || {};
let entry = (body.entry && body.entry[0]) ? body.entry[0] : {};
let changes = (entry.changes && entry.changes[0]) ? entry.changes[0] : {};
let value = changes.value || body.value || {};

// Ignore Meta WhatsApp status updates (delivered, sent, read, etc.)
if (value.statuses && (!value.messages || value.messages.length === 0)) {
  return []; // Stops execution cleanly for delivery/read receipts
}

let metadata = value.metadata || body.metadata || {};
let messages = (value.messages && value.messages[0]) ? value.messages[0] : (body.messages && body.messages[0] ? body.messages[0] : null);
let contacts = (value.contacts && value.contacts[0]) ? value.contacts[0] : (body.contacts && body.contacts[0] ? body.contacts[0] : {});

if (!messages && !body.message && !body.text) {
  return []; // No inbound message content to process
}
messages = messages || {};

const phone_number_id = metadata.phone_number_id || body.phone_number_id || '10023456789';
let sender_number   = messages.from || body.number || body.from || '';
let message_text    = '';
let button_id       = '';

if (messages.interactive && messages.interactive.button_reply) {
  button_id = messages.interactive.button_reply.id || '';
  message_text = button_id || messages.interactive.button_reply.title || '';
} else if (messages.interactive && messages.interactive.list_reply) {
  button_id = messages.interactive.list_reply.id || '';
  message_text = button_id || messages.interactive.list_reply.title || '';
} else if (messages.type === 'button' && messages.button) {
  button_id = messages.button.payload || messages.button.text || '';
  message_text = button_id || messages.button.text || '';
} else if (messages.type === 'location' && messages.location) {
  const loc = messages.location;
  message_text = `UBICACION: ${loc.latitude},${loc.longitude} (${loc.name || loc.address || ''})`.trim();
} else if (messages.text && messages.text.body) {
  message_text = messages.text.body;
} else {
  message_text = body.message || body.text || '';
}

const contact_name = (contacts.profile && contacts.profile.name) ? contacts.profile.name : (body.name || 'Cliente');
let media_url = '';
if (messages.type === 'image' && messages.image) {
  media_url = messages.image.id || messages.image.link || 'https://example.com/comprobante.jpg';
} else {
  media_url = body.media_url || '';
}

if (!sender_number && !message_text && !media_url) {
  return []; // Safeguard against empty payloads
}

return {
  phone_number_id,
  sender_number: (sender_number || '').trim(),
  message_text: (message_text || '').trim(),
  button_id: button_id || '',
  contact_name,
  media_url,
  timestamp: messages.timestamp || Math.floor(Date.now() / 1000)
};

const inputItems = $input.all();
const tenantRow = (inputItems.length > 0 && inputItems[0].json && inputItems[0].json.id) ? inputItems[0].json : null;
const meta = $('Code - Extract Meta Payload Data').item?.json || {};

if (!tenantRow || !tenantRow.id) {
  return {
    found: false,
    message: '⛔ Este número de WhatsApp Business no está registrado en el sistema.',
    sender_number: meta.sender_number,
    phone_number_id: meta.phone_number_id
  };
}

const isBusiness = (meta.sender_number === tenantRow.number);
return {
  found: true,
  tenant: {
    id: tenantRow.id,
    name: tenantRow.name,
    number: tenantRow.number,
    whatsapp_phone_number_id: tenantRow.whatsapp_phone_number_id,
    whatsapp_access_token: tenantRow.whatsapp_access_token,
    require_delivery_address: tenantRow.require_delivery_address !== false,
    enable_sales: tenantRow.enable_sales !== false,
    enable_crud: tenantRow.enable_crud !== false,
    enable_reports: tenantRow.enable_reports !== false,
    enable_appointments: tenantRow.enable_appointments !== false
  },
  sender: {
    type: isBusiness ? 'business' : 'client',
    number: meta.sender_number,
    name: isBusiness ? tenantRow.name : (meta.contact_name || 'Cliente')
  },
  message: {
    text: meta.message_text || '',
    button_id: meta.button_id || '',
    media_url: meta.media_url || '',
    timestamp: meta.timestamp || Math.floor(Date.now() / 1000)
  }
};

const upsertRes = $input.first() ? $input.first().json : {};
const ctx = $('Code - Evaluate Role Business or Client').item.json;

return {
  tenant: ctx.tenant,
  sender: {
    ...ctx.sender,
    client_id: upsertRes.id || ctx.sender.client_id
  },
  message: ctx.message
};

const ctx = $('Code - Evaluate Role Business or Client').item.json;
const rawOutput = $input.item.json.output || $input.item.json.text || '';
const msg = (ctx.message.text || '').toLowerCase().trim();
const btn = (ctx.message.button_id || '').toLowerCase().trim();
const isBusiness = ctx.sender.type === 'business';

let subflow = '';

// 1. Instant Fast Routing for Business Commands & Buttons
if (isBusiness) {
  if (
    btn === 'ver inventario' || btn === 'inventario' ||
    msg.startsWith('ver inventario') || msg.startsWith('inventario') || msg.startsWith('catalogo') || msg.startsWith('catálogo') ||
    msg.startsWith('crear producto') || msg.startsWith('agregar producto') || msg.startsWith('nuevo producto') ||
    msg.startsWith('agregar stock') || msg.startsWith('sumar stock') || msg.startsWith('añadir stock') ||
    msg.startsWith('restar stock') || msg.startsWith('quitar stock') || msg.startsWith('reducir stock') || msg.startsWith('descontar stock') ||
    msg.startsWith('cambiar precio') || msg.startsWith('actualizar precio') || msg.startsWith('precio de') ||
    msg.startsWith('eliminar producto') || msg.startsWith('borrar producto') || msg.startsWith('desactivar producto') ||
    msg.startsWith('eliminar ') || msg.startsWith('borrar ') || msg.startsWith('desactivar ') ||
    msg === 'inventario' || msg === 'catalogo' || msg === 'catálogo' || msg === 'productos'
  ) {
    subflow = 'crud';
  } else if (btn === 'tareas' || btn === 'pendientes' || msg === 'tareas' || msg === 'pendientes' || msg === 'pedidos') {
    subflow = 'sales';
  } else if (btn === 'despachos' || msg.startsWith('despachos') || msg.startsWith('aprobar') || msg.startsWith('rechazar') || msg.startsWith('pausar') || msg.startsWith('activar') || msg.startsWith('despachar')) {
    subflow = 'sales';
  } else if (btn === 'ver citas' || btn === 'citas' || msg.startsWith('ver citas') || msg.includes('agenda') || msg === 'citas') {
    subflow = 'appointments';
  } else if (btn === 'reporte' || btn === 'reportes' || msg.startsWith('reporte') || msg.startsWith('generar reporte') || msg.includes('balance') || msg.includes('ventas hoy')) {
    subflow = 'reports';
  } else if (btn === 'menu' || btn === 'ayuda' || msg === 'menu' || msg === 'ayuda' || msg === 'hola' || msg === 'buenas' || msg === 'inicio' || msg === 'comandos') {
    subflow = 'help_menu';
  }
} else {
  // Client Fast Routing
  if (btn.includes('cita') || msg.includes('agendar cita') || msg.includes('reservar')) {
    subflow = 'appointments';
  } else if (btn.includes('catalogo') || btn.includes('catálogo') || btn.includes('carrito') || btn.includes('comprar') || msg.startsWith('busco') || msg.startsWith('quiero') || msg.includes('precio') || msg === 'hola' || msg === 'buenas') {
    subflow = 'sales';
  }
}

// 2. Fallback to AI Agent classification if unstructured text
if (!subflow && rawOutput) {
  try {
    const jsonMatch = rawOutput.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      if (parsed.subflow) subflow = parsed.subflow;
    }
  } catch(e) {}
}

if (!subflow) {
  subflow = isBusiness ? 'help_menu' : 'sales';
}

// 3. Check tenant permissions for selected subflow
const t = ctx.tenant || {};
if (subflow === 'sales' && !t.enable_sales) subflow = 'help_menu';
if (subflow === 'crud' && !t.enable_crud) subflow = 'help_menu';
if (subflow === 'reports' && !t.enable_reports) subflow = 'help_menu';
if (subflow === 'appointments' && !t.enable_appointments) subflow = 'help_menu';

return {
  ...ctx,
  subflow: subflow || 'help_menu'
};
